int count = 0;
object _lock = new object();

// ❌ CAUSES A RACE CONDITION
public void IncrementBad() {
    count++; // Not thread-safe! (Read, Add, Write)
}

// ✅ THREAD-SAFE
public void IncrementGood() {
    lock(_lock) {
        count++;
    }
}

// ❌ BAD: Creates a useless background thread just to wait.
// This wastes thread pool resources.
await Task.Run(() => dbContext.Users.ToList());

// ✅ GOOD: Pure Async I/O.
// No threads are blocked. The SQL Server does the work!
await dbContext.Users.ToListAsync();
